    private static byte[]? DecodeHex(string? value)
    {
        return value is null ? null : Convert.FromHexString(value);
    }

    [Theory]
    [MemberData(nameof(SignatureCases))]
    public void SignatureVerificationHonorsStrictBoundary(
        string name,
        string? metadataHex,
        string? signatureHex,
        string? publicKeyHex,
        string expected)
    {
        Assert.False(string.IsNullOrWhiteSpace(name));

        byte[]? metadata = DecodeHex(metadataHex);
        byte[]? signature = DecodeHex(signatureHex);
        byte[]? publicKey = DecodeHex(publicKeyHex);

        var verifier = new TruthDoctorV3ReleaseSignatureVerifier();

        bool Execute() => verifier.Verify(
            metadata!, signature!, publicKey!);

        switch (expected)
        {
            case "VALID":
                Assert.True(Execute());
                break;

            case "INVALID":
                Assert.False(Execute());
                break;

            case "FORMAT":
                Assert.Throws<FormatException>(() => Execute());
                break;

            case "ARGUMENT":
                Assert.Throws<ArgumentException>(() => Execute());
                break;

            case "NULL":
                Assert.Throws<ArgumentNullException>(() => Execute());
                break;

            default:
                throw new InvalidOperationException(
                    "Unexpected test classification: " + expected);
        }
    }
}
